const items = $input.all().map(i => i.json); // agora cada item é uma linha da tabela

const categorias = ["urgente_prazo","duvida_processo","agendamento","financeiro","documento_recebido","spam_irrelevante"];

const contagem = {};
categorias.forEach(c => contagem[c] = 0);
items.forEach(item => {
  if (contagem[item.categoria] !== undefined) contagem[item.categoria]++;
});

const urgentes = items
  .filter(item => item.categoria === "urgente_prazo")
  .sort((a, b) => new Date(a.data_prazo || '9999-12-31') - new Date(b.data_prazo || '9999-12-31'));

const hoje = new Date().toISOString().split('T')[0];

let texto = `📋 Resumo Diário de Mensagens — ${hoje}\n`;
texto += `Total de mensagens: ${items.length}\n\n`;

if (urgentes.length > 0) {
  texto += `🔴 URGENTES (${urgentes.length})\n`;
  urgentes.forEach((item, idx) => {
    const ehParteContraria = item.remetente_tipo === "parte_contraria";
    const cliente = item.nome_cliente || (ehParteContraria ? "Parte contrária" : "Não identificado");
    const alerta = ehParteContraria ? " ⚠️ (parte contrária, não é cliente)" : "";
    texto += `${idx + 1}. ${cliente} — Processo: ${item.numero_processo || "não informado"} — Prazo: ${item.data_prazo || "não informado"}${alerta}\n`;
  });
  texto += `\n`;
} else {
  texto += `🔴 URGENTES: nenhuma mensagem urgente hoje.\n\n`;
}

texto += `Por categoria:\n`;
categorias.forEach(c => { texto += `- ${c}: ${contagem[c]}\n`; });

return [{
  json: {
    data: hoje,
    total_mensagens: items.length,
    total_urgentes: urgentes.length,
    categorias_json: contagem, // deixamos como objeto — o node Supabase de gravação serializa sozinho
    resumo_texto: texto
  }
}];
